package com.ruoyi.metal.service;
import java.util.*;import org.junit.jupiter.api.Test;import com.ruoyi.metal.catalog.*;import com.ruoyi.metal.security.FactoryScope;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class BusinessFiltersTest {
 @Test void literalPatternsAndInclusiveEndDate(){assertEquals("%a!%!_!!%",ListQuery.pattern("a%_!"));var q=new ListQuery();q.setStartDate("2026-10-01");q.setEndDate("2026-10-15");q.validate();assertEquals("2026-10-16T00:00",q.getEndExclusive().toString());q.setName("  ");assertNull(q.getNamePattern());q.setEndDate("2026-09-30");assertThrows(RuntimeException.class,q::validate);}
 @Test void factoryCannotBeOverriddenByListOrExportFilter(){var scope=mock(FactoryScope.class);when(scope.currentFactory()).thenReturn(2L);var queries=new BusinessQueries(scope);var q=new OrderListQuery();q.setFactoryId(3L);assertThrows(RuntimeException.class,()->queries.orders(q));var staff=new ListQuery();staff.setFactoryId(3L);assertThrows(RuntimeException.class,()->queries.staff(staff));}
 @Test void peopleUseJsonMembershipAndRolesUseExists(){var scope=mock(FactoryScope.class);when(scope.currentFactory()).thenReturn(2L);var q=new OrderListQuery();q.setOperatorId(12L);q.setOrderNo("A_%");q.setWorkOrderNo("WO-1");q.setStartDate("2026-10-01");q.setEndDate("2026-10-15");var result=new BusinessQueries(scope).orders(q);assertTrue(result.sql().contains("JSON_CONTAINS"));assertTrue(result.sql().contains("EXISTS"));assertFalse(result.sql().contains("A_%"));assertTrue(result.args().contains("%A!_!%%"));assertTrue(result.args().contains("12"));var staff=new ListQuery();staff.setRoleId(3L);assertTrue(new BusinessQueries(scope).staff(staff).sql().contains("EXISTS"));}
 @Test void exportsAllPagesAndExcludesSensitiveColumns()throws Exception{
  var jdbc=mock(org.springframework.jdbc.core.JdbcTemplate.class);var scope=mock(FactoryScope.class);when(scope.currentFactory()).thenReturn(2L);var queries=new BusinessQueries(scope);
  when(jdbc.queryForList(anyString(),any(Object[].class))).thenAnswer(a->{Object[] args=(Object[])a.getRawArguments()[1];int offset=((Number)args[args.length-1]).intValue();var rows=new ArrayList<Map<String,Object>>();for(int i=offset;i<Math.min(offset+1000,1001);i++)rows.add(new HashMap<>(Map.of("user_name","001"+i,"phonenumber","13800000000","nick_name","测试人员","password","must-not-export","token","must-not-export")));return rows;});
  var output=new java.io.ByteArrayOutputStream();assertEquals(1001,new BusinessExportService(jdbc,queries).staff(new ListQuery(),output));try(var book=new org.apache.poi.xssf.usermodel.XSSFWorkbook(new java.io.ByteArrayInputStream(output.toByteArray()))){var sheet=book.getSheetAt(0);assertEquals(1001,sheet.getLastRowNum());assertEquals("0010",sheet.getRow(1).getCell(0).getStringCellValue());assertEquals(7,sheet.getRow(0).getLastCellNum());for(var row:sheet)for(var cell:row)assertFalse(cell.toString().contains("must-not-export"));}
 }
}
